import com.google.gson.JsonParser;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch75Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("sm9_en_148","swsh11_en_165");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static TrainerProfile profile(String id){return NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();}
    static GeneratedRuleBatch28Test.Config config(String id,AttackDefinition attack,boolean metal){var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile(id);c.attack=attack;c.defenderAttack=attack;c.ownTypes=Set.of(metal?EnergyType.METAL:EnergyType.FIRE);c.defenderTypes=c.ownTypes;return c;}
    static ServerMatch fixture(GeneratedRuleBatch28Test.Config c,UUID p){var m=GeneratedRuleBatch28Test.fixture(c);if(p.equals(B))m.endTurn(A);return m;}
    static void equip(ServerMatch m,UUID p,UUID host){m.attachToolByEffect(m.currentPlayer(),p,EffectSourceZone.HAND,hand(m,p,"trainer").instanceId(),p,host);}
    static void hurt(ServerMatch m,UUID owner,UUID host,int damage){for(int left=damage;left>0;){int n=Math.min(left,600);m.placeDamageCountersByEffect(m.currentPlayer(),owner,host,n/10);left-=n;}}
    static ServerMatch aiGame(String id){var m=fixture(config(id,GeneratedRuleBatch8Test.hit(100,false),true),A);if(id.equals(IDS.get(1)))hurt(m,B,active(m,B),960);return m;}
    public static void main(String[] args){metalDamage();liveType();counterOrigins();checkup();retaliation();panic();timing();schema();System.out.println("NonPokemonBatch75Test passed: both owners/positions, live Metal type and Tool suppression, attack/Ability/checkup counter protection, Trainer/own/status exceptions, retaliation, Panic Mask 10/40/50/100 HP and before/after damage timing, removal, native Shred and damage/effects distinction");}
    static void metalDamage(){for(UUID p:List.of(A,B))for(boolean metal:List.of(false,true))for(boolean disabled:List.of(false,true))for(boolean benched:List.of(false,true)){
        var attack=DamageTriggeredAbilityTest.attack(100,",\"damageTarget\":\"ALL_OPPONENT_POKEMON\"");var m=fixture(config(IDS.getFirst(),attack,metal),p);UUID target=benched?bench(m,p):active(m,p);equip(m,p,target);if(disabled)m.disableToolEffectsByEffect(p,p,target);m.endTurn(p);m.attack(other(p),"hit");NonPokemonBatch67Test.settle(m);int expected=metal&&!disabled?70:100;var view=benched?m.benchPokemonView(p).getFirst():m.activePokemonView(p);check(view.damage()==expected,"Metal Goggles type, owner, position or suppression wrong");
    }}
    static void liveType(){for(UUID p:List.of(A,B)){var m=fixture(config(IDS.getFirst(),GeneratedRuleBatch8Test.hit(100,false),true),p);equip(m,p,active(m,p));m.evolveByEffect(p,active(m,p),hand(m,p,p.equals(A)?"evolved":"defender_evolved").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);m.endTurn(p);m.attack(other(p),"hit");NonPokemonBatch67Test.settle(m);check(m.activePokemonView(p).damage()==100,"Metal Goggles retained protection after evolving to non-Metal");}}
    static void counterOrigins(){for(boolean disabled:List.of(false,true))for(String source:List.of("attack","ability","own","trainer")){
        String effects="{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":2},{\"type\":\"poison\",\"target\":\"OPPONENT_ACTIVE\"}";var ability=GeneratedRuleBatch31Test.counterAbility(source.equals("own")?"SELF":"OPPONENT_ACTIVE");var c=config(IDS.getFirst(),DeckDiscardTriggeredAbilityTest.attack(0,effects),true);c.ownAbility=ability;var m=fixture(c,A);UUID owner=source.equals("own")?A:B;equip(m,owner,active(m,owner));if(disabled)m.disableToolEffectsByEffect(A,owner,active(m,owner));
        if(source.equals("attack")){m.attack(A,"hit");NonPokemonBatch67Test.settle(m);check(m.activePokemonView(B).damage()==(disabled?30:10)&&m.activePokemonView(B).conditions().contains(SpecialCondition.POISONED),"Metal Goggles blocked status or failed attack counter protection");}
        else if(source.equals("trainer")){var item=DeckDiscardTriggeredAbilityTest.trainer("ITEM","{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":2}");var n=DynamicPassiveModifierTest.fixture(profile(IDS.getFirst()),DynamicPassiveModifierTest.plainStadium(),EnergyProfile.basic(EnergyType.COLORLESS),GeneratedRuleBatch8Test.hit(10,false),List.of(),0,item,Map.of("basic",EnergyType.METAL,"evolved",EnergyType.METAL));n.attachToolByEffect(A,B,EffectSourceZone.HAND,hand(n,B,"tool").instanceId(),B,active(n,B));n.playTrainer(A,hand(n,A,"item").instanceId(),null);NonPokemonBatch67Test.settle(n);check(n.activePokemonView(B).damage()==20,"Metal Goggles incorrectly blocked Trainer counters");}
        else{m.useAbility(A,active(m,A),ability.id());NonPokemonBatch67Test.settle(m);check(m.activePokemonView(owner).damage()==(disabled||source.equals("own")?20:0),"Metal Goggles wrong Ability owner scope");}
    }}
    static void checkup(){for(boolean disabled:List.of(false,true)){var c=config(IDS.getFirst(),GeneratedRuleBatch8Test.hit(10,false),true);c.source=CheckupTriggeredAbilityTest.ability("counter-checkup",false,"{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":2}");var m=fixture(c,A);m.playBasicPokemonToBench(A,hand(m,A,"source").instanceId());m.switchActiveByEffect(A,A,m.benchPokemonView(A).stream().filter(v->v.topCardId().equals("source")).findFirst().orElseThrow().pokemonId());equip(m,B,active(m,B));if(disabled)m.disableToolEffectsByEffect(A,B,active(m,B));m.endTurn(A);NonPokemonBatch67Test.settle(m);check(m.activePokemonView(B).damage()==(disabled?20:0),"Metal Goggles lost source identity during Checkup");}}
    static void retaliation(){var m=fixture(config(IDS.getFirst(),GeneratedRuleBatch8Test.hit(100,false),true),A);equip(m,A,active(m,A));EventTargetBindingTest.field(m).retaliateUntilOwnerNextTurn(B,A,B,active(m,B),3);m.attack(A,"hit");NonPokemonBatch67Test.settle(m);check(m.activePokemonView(A).damage()==0,"Delayed attack counter retaliation bypassed Metal Goggles");}
    static void panic(){for(UUID p:List.of(A,B))for(int remaining:List.of(10,40,50,100))for(boolean disabled:List.of(false,true))for(boolean benched:List.of(false,true)){
        var attack=DamageTriggeredAbilityTest.attack(100,",\"damageTarget\":\"ALL_OPPONENT_POKEMON\"");var m=fixture(config(IDS.get(1),attack,false),p);UUID target=benched?bench(m,p):active(m,p);equip(m,p,target);hurt(m,other(p),active(m,other(p)),1000-remaining);if(disabled)m.disableToolEffectsByEffect(p,p,target);m.endTurn(p);m.attack(other(p),"hit");NonPokemonBatch67Test.settle(m);var view=benched?m.benchPokemonView(p).getFirst():m.activePokemonView(p);check(view.damage()==(!disabled&&remaining<=40?0:100),"Panic Mask threshold/source/position/suppression wrong");
    }}
    static void timing(){
        for(boolean before:List.of(false,true)){var effects="{\"type\":\"damage_counter\",\"target\":\"SELF\",\"amount\":6}";var attack=BeforeDamageAttackTest.attack(before?effects:"","",before?"":effects);var m=fixture(config(IDS.get(1),attack,false),A);equip(m,B,active(m,B));hurt(m,A,active(m,A),900);m.attack(A,attack.id());NonPokemonBatch67Test.settle(m);check(m.activePokemonView(A).damage()==960&&m.activePokemonView(B).damage()==(before?0:40),"Panic Mask used post-damage HP or stale pre-cost HP");}
        for(String mode:List.of("remove","shred","effect")){String before=mode.equals("remove")?"{\"type\":\"discard_tool\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":60,\"minimum\":60}":"";String after=mode.equals("effect")?"{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":2}":"";var attack=mode.equals("shred")?DamageTriggeredAbilityTest.attack(100,",\"ignoresActiveDefenderDamageEffects\":true"):BeforeDamageAttackTest.attack(before,"",after);var m=fixture(config(IDS.get(1),attack,false),A);equip(m,B,active(m,B));hurt(m,A,active(m,A),960);m.attack(A,attack.id());NonPokemonBatch67Test.settle(m);check(m.activePokemonView(B).damage()==(mode.equals("shred")?100:mode.equals("effect")?20:40),"Panic Mask ignored removal/Shred or blocked effects");}
        var hp=DynamicPassiveModifierTest.trainer("TOOL","{\"type\":\"hit_points_modifier\",\"target\":\"SELF\",\"amount\":30}");var attack=BeforeDamageAttackTest.attack("{\"type\":\"discard_tool\",\"target\":\"SELF\",\"amount\":60,\"minimum\":60}","","");var m=DynamicPassiveModifierTest.fixture(profile(IDS.get(1)),DynamicPassiveModifierTest.plainStadium(),EnergyProfile.basic(EnergyType.COLORLESS),attack,List.of(),0,hp);m.playTrainer(A,hand(m,A,"item").instanceId(),active(m,A));m.attachToolByEffect(A,B,EffectSourceZone.HAND,hand(m,B,"tool").instanceId(),B,active(m,B));hurt(m,A,active(m,A),260);check(m.activePokemonView(A).hitPoints()-m.activePokemonView(A).damage()==70,"HP Tool timing fixture wrong");m.attack(A,attack.id());NonPokemonBatch67Test.settle(m);check(m.activePokemonView(A).hitPoints()-m.activePokemonView(A).damage()==40&&m.activePokemonView(B).damage()==0,"Panic Mask did not account for HP Tool discarded before damage");
    }
    static void schema(){for(String effect:List.of("{\"type\":\"prevent_opponent_attack_ability_counters\",\"target\":\"OWN_BENCH\"}","{\"type\":\"passive_attack_guard\",\"target\":\"SELF\",\"mode\":\"PREVENT\",\"attacker_remaining_hp_max\":50}"))GeneratedRuleBatch8Test.reject(()->EffectRegistry.standard().parse(JsonParser.parseString(effect).getAsJsonObject()));}
}
